// Applied rules: [III④, III③]
// Skipped rules: [III④: Hits [2,5,6,7,8,9] are on the output/match-copy side of an LZ4 decode loop with data-dependent backward/overlapping reads from `op - offset`; III④ explicitly says to abstain when no forward iterator form exists, and §5.1 forbids replacing the forward bytewise propagation loop with slice/memmove-style copying.; III③: Do not rewrite the in-loop `libc::memmove` calls in this hot decompression kernel; the card's hot decode/compress loop perf abstain applies, and overlap tolerance is semantically required for some copies.]
#[inline(always)]
unsafe fn LZ4_decompress_unsafe_generic(
    istart: *const BYTE,
    ostart: *mut BYTE,
    mut decompressedSize: c_int,
    mut prefixSize: size_t,
    dictStart: *const BYTE,
    dictSize: size_t,
) -> c_int {
    let mut ip: *const BYTE = istart;
    let mut op: *mut BYTE = ostart;
    let oend: *mut BYTE = ostart.offset(decompressedSize as isize);
    let prefixStart: *const BYTE = ostart.offset(-(prefixSize as isize));
    dictStart.is_null();
    loop {
        let token: c_uint = {
            // SAFETY: `ip` is the current input cursor into the caller-provided compressed buffer;
            // this function's existing decode invariants permit consuming one token byte here,
            // `ip` is non-null as derived from `istart`, and this shared slice reborrow does not
            // alias the mutable output region.
            let in1 = unsafe { core::slice::from_raw_parts(ip, 1) };
            ip = ip.offset(1);
            in1[0] as c_uint
        };
        let mut ll: size_t = (token >> ML_BITS) as size_t;
        if ll == 15 as size_t {
            ll = ll.wrapping_add(read_long_length_no_check(&raw mut ip));
        }
        if (oend.offset_from(op) as c_long as size_t) < ll {
            return -(1 as c_int);
        }
        ::libc::memmove(
            op as *mut c_void,
            ip as *const c_void,
            ll as ::libc::size_t,
        );
        op = op.offset(ll as isize);
        ip = ip.offset(ll as isize);
        if (oend.offset_from(op) as c_long as size_t) < MFLIMIT as size_t {
            if op == oend {
                break;
            }
            return -(1 as c_int);
        } else {
            let mut ml: size_t = (token & 15 as c_uint) as size_t;
            let offset: size_t = {
                // SAFETY: `ip` is the current input cursor and the existing decode invariants
                // permit consuming the 2-byte little-endian offset here; `ip` is non-null as
                // derived from `istart`, and this shared slice reborrow does not alias the
                // mutable output region.
                let in2 = unsafe { core::slice::from_raw_parts(ip, 2) };
                ip = ip.offset(2 as c_int as isize);
                u16::from_le_bytes([in2[0], in2[1]]) as size_t
            };
            if ml == 15 as size_t {
                ml = ml.wrapping_add(read_long_length_no_check(&raw mut ip));
            }
            ml = ml.wrapping_add(MINMATCH as size_t);
            if (oend.offset_from(op) as c_long as size_t) < ml {
                return -(1 as c_int);
            }
            let mut match_0: *const BYTE = op.offset(-(offset as isize));
            if offset
                > (op.offset_from(prefixStart) as c_long as size_t)
                    .wrapping_add(dictSize)
            {
                return -(1 as c_int);
            }
            if offset > op.offset_from(prefixStart) as c_long as size_t {
                let dictEnd: *const BYTE = dictStart.offset(dictSize as isize);
                let mut extMatch: *const BYTE = dictEnd.offset(
                    -(offset
                        .wrapping_sub(op.offset_from(prefixStart) as c_long as size_t)
                        as isize),
                );
                let extml: size_t = dictEnd.offset_from(extMatch) as c_long as size_t;
                if extml > ml {
                    ::libc::memmove(
                        op as *mut c_void,
                        extMatch as *const c_void,
                        ml as ::libc::size_t,
                    );
                    op = op.offset(ml as isize);
                    ml = 0 as size_t;
                } else {
                    ::libc::memmove(
                        op as *mut c_void,
                        extMatch as *const c_void,
                        extml as ::libc::size_t,
                    );
                    op = op.offset(extml as isize);
                    ml = ml.wrapping_sub(extml);
                }
                match_0 = prefixStart;
            }
            let mut u: size_t = 0;
            u = 0 as size_t;
            while u < ml {
                *op.offset(u as isize) = *match_0.offset(u as isize);
                u = u.wrapping_add(1);
            }
            op = op.offset(ml as isize);
            if (oend.offset_from(op) as c_long as size_t) < LASTLITERALS as size_t {
                return -(1 as c_int);
            }
        }
    }
    return ip.offset_from(istart) as c_long as c_int;
}

